const rows = $input.all().map(item => {
  const r = item.json;
  const normalized = {};
  for (const [key, value] of Object.entries(r)) {
    normalized[key.trim().toLowerCase()] = value;
  }
  return normalized;
});

const reviews = rows
  .filter(r => r.review_text && r.review_date)
  .map((r, i) => ({
    review_id: String(r.review_id || `ROW-${i + 1}`),
    review_date: String(r.review_date).trim(),
    rating: Number(r.rating || 0),
    review_text: String(r.review_text).trim(),
    source: String(r.source || ''),
    source_url: String(r.source_url || '')
  }));

if (reviews.length < 3) {
  throw new Error(`Only ${reviews.length} reviews found.`);
}

return [{
  json: {
    product: 'Groww',
    review_count: reviews.length,
    reviewsJson: JSON.stringify(reviews)
  }
}];

const item = $input.first().json;

// Extract the model response from the OpenAI node.
const rawText =
  item.output?.[0]?.content?.find(c => c.type === 'output_text')?.text
  ?? item.output?.[0]?.content?.[0]?.text
  ?? item.text
  ?? item.message?.content;

if (typeof rawText !== 'string' || !rawText.trim()) {
  throw new Error(
    'Could not find the AI response text. Inspect the Message a model output.'
  );
}

let analysis;

try {
  // Remove optional Markdown code fences if present.
  const cleaned = rawText
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  analysis = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `AI response is not valid JSON: ${error.message}`
  );
}

if (!Array.isArray(analysis.themes)) {
  throw new Error('Missing or invalid themes array.');
}

if (!Array.isArray(analysis.top_3_themes)) {
  throw new Error('Missing or invalid top_3_themes array.');
}

if (!Array.isArray(analysis.user_quotes)) {
  throw new Error('Missing or invalid user_quotes array.');
}

if (!analysis.fee_issue || typeof analysis.fee_issue.identified !== 'boolean') {
  throw new Error('Missing or invalid fee_issue.');
}

return [{
  json: {
    product: 'Groww',
    analysis,
    themes: analysis.themes,
    top_3_themes: analysis.top_3_themes,
    user_quotes: analysis.user_quotes,
    fee_issue: analysis.fee_issue,
    limitations: analysis.limitations || []
  }
}];

const item = $input.first().json;

// Extract text from the OpenAI Message a model output.
const raw = item.output?.[0]?.content?.find(
  c => c.type === 'output_text'
)?.text ?? item.output?.[0]?.content?.[0]?.text;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error(
    'Could not find response text. Check Generate Pulse and Fee Explainer output.'
  );
}

const cleaned = raw.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '');

let data;

try {
  data = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`AI response is not valid JSON: ${e.message}`);
}

// Validate weekly pulse.
if (typeof data.weekly_pulse !== 'string' || !data.weekly_pulse.trim()) {
  throw new Error('weekly_pulse is missing or empty.');
}

const wordCount = data.weekly_pulse.trim().split(/\s+/).length;

if (wordCount > 250) {
  throw new Error(`Weekly pulse exceeds 250 words (${wordCount}).`);
}

// Validate fee explainer.
const fee = data.fee_explainer;

if (!fee || typeof fee !== 'object') {
  throw new Error('fee_explainer is missing.');
}

if (!Array.isArray(fee.bullets)) {
  throw new Error('fee_explainer.bullets must be an array.');
}

if (fee.bullets.length > 6) {
  throw new Error('Fee explainer exceeds six bullets.');
}

if (!Array.isArray(fee.official_sources)) {
  throw new Error('official_sources must be an array.');
}

if (fee.applicable && fee.official_sources.length < 2) {
  throw new Error('An applicable fee explainer needs two official sources.');
}

return [{
  json: {
    product: 'Groww',
    weekly_pulse: data.weekly_pulse,
    fee_explainer: fee,
    validation: {
      passed: true,
      weekly_pulse_word_count: wordCount,
      fee_bullet_count: fee.bullets.length
    }
  }
}];
